Item.Value:
SELECT * 
FROM VW_RM_List
WHERE CompanyID = {0} AND ListID = {1}

SELECT SR.* ,DC.DeptBase, DC.DeptKo, DC.DeptEn, DC.DeptJa, DC.DeptFr, DC.DeptZhcn, DC.DeptZhtw ,DC.TitleBase, DC.TitleKo, DC.TitleEn, DC.TitleJa, DC.TitleFr, DC.TitleZhcn, DC.TitleZhtw
	FROM DP_RM_ShortReply AS SR WITH(NOLOCK) LEFT OUTER JOIN DP_COM_DeptCode AS DC WITH(NOLOCK) ON SR.CompanyID = DC.CompanyID AND SR.DeptCodeID = DC.DeptCodeID  
	WHERE SR.CompanyID = {0} AND SR.ReservationID = {1}

SELECT R.* ,DC.DeptBase, DC.DeptKo, DC.DeptEn, DC.DeptJa, DC.DeptFr, DC.DeptZhcn, DC.DeptZhtw ,DC.TitleBase, DC.TitleKo, DC.TitleEn, DC.TitleJa, DC.TitleFr, DC.TitleZhcn, DC.TitleZhtw
	FROM DP_RM_Reject AS R WITH(NOLOCK) LEFT OUTER JOIN DP_COM_DeptCode AS DC WITH(NOLOCK) ON R.CompanyID = DC.CompanyID AND R.DeptCodeID = DC.DeptCodeID  
	WHERE R.CompanyID = {0} AND R.ReservationID = {1}

SELECT * 
            FROM DP_RM_Attach 
            WHERE CompanyID = {0} 
            AND CategoryID = {1}
            AND ListID = {2}
            AND Gubun = {3}
